L2:(2) Testing;
L2:(3) Research;
L2:(4) Manufacturing;
L2:(5) Handling or loading;
L2:(6) Assembling;
L2:(7) Packaging;
L2:(8) Storage;
L2:(9) Transportation;
L2:(10) Renovation;
L2:(11) Demilitarization;
L2:(12) Modification;
L2:(13) Repair;
L2:(14) Disposal;
L2:(15) Inspection; or
